def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1
    last_opp = history[-1][1]
    if opp_def == 0:
        if n < 2:
            return 'C'
        return 'D'
    opp_def_rate = opp_def / n
    if opp_def_rate > 0.5:
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if last_opp == 'D':
        if rng.random() < 0.8:
            return 'C'
        return 'D'
    return 'C'
